5	/// A single `EntryRecordCard`'s own sync badge (AD-10) — exactly the 3
6	/// states `docs/input/backend/sync-badge.md` names, never a 4th: the
7	/// server exposes no sync field of its own, so these 3 are the complete
8	/// set this app ever needs to render. Sealed, with `const factory`
9	/// constructors on the base class (mirrors `Failure`'s own shape, minus
10	/// the `freezed` codegen — no `==`/`copyWith` machinery is needed here
11	/// beyond the hand-rolled equality each subclass already carries) so call
12	/// sites read as `SyncBadgeState.synchronizing()` rather than naming each
13	/// subclass directly.
14	sealed class SyncBadgeState {
15	  const SyncBadgeState();
16	
17	  const factory SyncBadgeState.synchronizing() = SyncBadgeSynchronizing;
18	
19	  const factory SyncBadgeState.synchronized() = SyncBadgeSynchronized;
20	
21	  const factory SyncBadgeState.error(Failure failure) = SyncBadgeError;
22	}
23	
24	/// "Synchronizing" (ochre) — a local write not yet confirmed by the
25	/// server.
26	class SyncBadgeSynchronizing extends SyncBadgeState {
27	  const SyncBadgeSynchronizing();
28	
29	  @override
30	  bool operator ==(Object other) => other is SyncBadgeSynchronizing;
31	
32	  @override
33	  int get hashCode => (SyncBadgeSynchronizing).hashCode;
34	
35	  @override
36	  String toString() => 'SyncBadgeSynchronizing()';
37	}
38	
39	/// "Synchronized" (green) — nothing pending for this entry; the last
40	/// confirmed write matched.
41	class SyncBadgeSynchronized extends SyncBadgeState {
42	  const SyncBadgeSynchronized();
43	
44	  @override
45	  bool operator ==(Object other) => other is SyncBadgeSynchronized;
46	
47	  @override
48	  int get hashCode => (SyncBadgeSynchronized).hashCode;
49	
50	  @override
51	  String toString() => 'SyncBadgeSynchronized()';
52	}
53	
54	/// "Synchronization error" (red) — the write was attempted and failed,
55	/// never yet reconciled. [failure] is kept so the badge's own tap handler
56	/// (`SyncBadge`) can read [Failure.retryable]/[Failure.message] directly,
57	/// per the Boundaries' "Tap on error badge" rule.
58	class SyncBadgeError extends SyncBadgeState {
59	  const SyncBadgeError(this.failure);
60	
61	  final Failure failure;
62	
63	  @override
64	  bool operator ==(Object other) =>
65	      identical(this, other) ||
66	      (other is SyncBadgeError && other.failure == failure);
67	
68	  @override
69	  int get hashCode => failure.hashCode;
70	
71	  @override
72	  String toString() => 'SyncBadgeError(failure: $failure)';
73	}
74	
75	/// The one place this app ever decides a card's badge (Never: "any screen
76	/// recomputing badge state inline") — pure, no I/O, no `package:flutter`
77	/// import (RNF06).
78	///
79	/// [pending] wins whenever it's non-null, regardless of [entry] — per
80	/// `sync-badge.md`, "Synchronizing"/"Synchronization error" both describe
81	/// *client-side pending state*, not anything read off [entry] itself, so a
82	/// pending write's own status is always the authoritative answer for
83	/// whichever card it belongs to. Once [pending] is `null`, the existence of
84	/// a confirmed [entry] already means "it is on the server" (sync-
85	/// badge.md: "it is on the server already means synchronized, by
86	/// definition") -> [SyncBadgeSynchronized]. [entry] and [pending] both
87	/// `null` is unreachable from every real caller (`MeusRegistrosLoaded`
88	/// always derives a displayed card from one or the other, never neither)
89	/// but still resolves to [SyncBadgeSynchronized] rather than throwing
90	/// (RNF09-style defensiveness) — "nothing pending" is the closest true
91	/// reading of that combination regardless of [entry].
92	SyncBadgeState deriveSyncBadgeState(Entry? entry, PendingEntryWrite? pending) {
93	  if (pending != null) {
94	    return switch (pending.status) {
95	      PendingEntryWriteInFlight() => const SyncBadgeState.synchronizing(),
96	      PendingEntryWriteFailed(failure: final failure) => SyncBadgeState.error(
97	        failure,
98	      ),
99	    };
100	  }
101	  return const SyncBadgeState.synchronized();
102	}
