6	/// `MeusRegistrosScreen`'s own sealed state — never the shared
7	/// `Resource<T>` (Boundaries, mirrors `capture`'s `TextEntryState`
8	/// sealed-class convention, `resource.dart`'s own doc already excludes
9	/// RF07 the same way): this screen's shape — a first load, a grouped list
10	/// with its own pagination sub-state, an empty result, or a terminal
11	/// error — doesn't fit that single-fetch lifecycle.
12	sealed class MeusRegistrosState {
13	  const MeusRegistrosState();
14	}
15	
16	/// The first page is in flight — `MeusRegistrosScreen` shows a skeleton
17	/// for this only past the shared 300ms threshold (RNF01), mirroring
18	/// `BootSplashScreen`'s own `Timer` pattern; blank below it.
19	class MeusRegistrosLoading extends MeusRegistrosState {
20	  const MeusRegistrosLoading();
21	}
22	
23	/// The first page resolved with zero entries — `MeusRegistrosScreen`'s
24	/// `_EmptyState` renders the prototype's Tela 4 — Vazio dedicated empty
25	/// state (icon, copy, "Criar primeiro registro" CTA opening the Insertion
26	/// Modal) for this (story 4.3).
27	class MeusRegistrosEmpty extends MeusRegistrosState {
28	  const MeusRegistrosEmpty();
29	}
30	
31	/// The first load failed with a `Failure` the repository's own
32	/// offline/Hive fallback never absorbs (e.g. `Failure.authExpired`) —
33	/// [message] is `Failure.message` verbatim, same convention
34	/// `TextEntryError.message` already uses.
35	class MeusRegistrosError extends MeusRegistrosState {
36	  const MeusRegistrosError({required this.message});
37	
38	  final String message;
39	
40	  @override
41	  bool operator ==(Object other) =>
42	      identical(this, other) ||
43	      (other is MeusRegistrosError && other.message == message);
44	
45	  @override
46	  int get hashCode => message.hashCode;
47	
48	  @override
49	  String toString() => 'MeusRegistrosError(message: $message)';
50	}
51	
52	/// A resolved page — [entries] accumulates every page fetched so far
53	/// (first load plus every successful [MeusRegistrosCubit.loadMore]),
54	/// already de-duplicated by id. [groups] re-derives the grouped view via
55	/// the pure `groupEntriesByDate()` on every read rather than this state
56	/// storing a separately-maintained, pre-grouped copy that `loadMore` would
57	/// otherwise have to keep in sync by hand.
58	class MeusRegistrosLoaded extends MeusRegistrosState {
59	  const MeusRegistrosLoaded({
60	    required this.entries,
61	    required this.nextCursor,
62	    this.isLoadingMore = false,
63	    this.loadMoreFailed = false,
64	    this.pendingWrites = const [],
65	  });
66	
67	  final List<Entry> entries;
68	
69	  /// `null` once the server's `meta.nextCursor` says there's no further
70	  /// page — also always `null` for a page served from the offline Hive
71	  /// fallback (Boundaries).
72	  final String? nextCursor;
73	
74	  /// `true` for the duration of one in-flight `loadMore()` call —
75	  /// `MeusRegistrosScreen`'s list footer shows a small spinner for this,
76	  /// distinct from the first load's full-screen skeleton.
77	  final bool isLoadingMore;
78	
79	  /// `true` after a `loadMore()` attempt fails — I/O matrix: "keeps
80	  /// current items + inline retry". [entries] is left exactly as it was;
81	  /// only the footer switches to a retry affordance.
82	  final bool loadMoreFailed;
83	
84	  /// spec-4-2 — every write `PendingEntryWriteTracker` currently holds
85	  /// (in flight or failed), mirrored from its own `pendingWrites` stream
86	  /// by `MeusRegistrosCubit`. Never contains a write that's already
87	  /// confirmed — that one has already moved into [entries] instead
88	  /// (`MeusRegistrosCubit._onEntryConfirmed`).
89	  final List<PendingEntryWrite> pendingWrites;
90	
91	  /// [entries] with each [pendingWrites] member rendered as its own
92	  /// placeholder [Entry] (content/source/[mediaDurationSeconds] from the
93	  /// pending write itself; `occurredAt` = [PendingEntryWrite.startedAt]),
94	  /// prepended ahead of [entries] — Boundaries: "Card appears top-of-
95	  /// today... before server responds". Grouping this combined list by day
96	  /// (via the same [groupEntriesByDate] every confirmed entry already
97	  /// uses) naturally lands a pending write's own card at the top of
98	  /// "Hoje", with no separate rendering path needed in the screen itself.
99	  ///
100	  /// [pendingWrites] itself holds insertion order (oldest-started first,
101	  /// `PendingEntryWriteTrackerImpl`'s own `Map` — Review finding, round 2):
102	  /// reversed here so two writes pending at once still land newest-first,
103	  /// matching [groupEntriesByDate]'s documented "callers always pass
104	  /// entries already newest-first" contract.
105	  List<Entry> get _displayEntries => [
106	    for (final pending in pendingWrites.reversed) _placeholderEntryFor(pending),
107	    ...entries,
108	  ];
109	
110	  List<EntryDateGroup> get groups => groupEntriesByDate(_displayEntries);
111	
112	  /// [entry]'s own badge (Code Map/Never: the one call site for
113	  /// `deriveSyncBadgeState()` outside its own unit tests). [entry] is
114	  /// looked up against [pendingWrites] by id — a placeholder [Entry]
115	  /// built by [_displayEntries] always has [PendingEntryWrite.tempId] as
116	  /// its [Entry.id], so this matches it back to its own pending write; a
117	  /// genuinely confirmed [Entry] from [entries] never matches one (the
118	  /// tracker's own `create()`/`retry()` already remove a pending record
119	  /// before `MeusRegistrosCubit` ever prepends the matching confirmed
120	  /// entry, so the two can never coexist here).
121	  SyncBadgeState badgeFor(Entry entry) {
122	    for (final pending in pendingWrites) {
123	      if (pending.tempId == entry.id) {
124	        return deriveSyncBadgeState(null, pending);
125	      }
126	    }
127	    return deriveSyncBadgeState(entry, null);
128	  }
129	
130	  MeusRegistrosLoaded copyWith({
131	    List<Entry>? entries,
132	    String? nextCursor,
133	    bool? isLoadingMore,
134	    bool? loadMoreFailed,
135	    List<PendingEntryWrite>? pendingWrites,
136	  }) {
137	    return MeusRegistrosLoaded(
138	      entries: entries ?? this.entries,
139	      nextCursor: nextCursor ?? this.nextCursor,
140	      isLoadingMore: isLoadingMore ?? this.isLoadingMore,
141	      loadMoreFailed: loadMoreFailed ?? this.loadMoreFailed,
142	      pendingWrites: pendingWrites ?? this.pendingWrites,
143	    );
144	  }
145	
146	  @override
147	  bool operator ==(Object other) =>
148	      identical(this, other) ||
149	      (other is MeusRegistrosLoaded &&
150	          other.nextCursor == nextCursor &&
151	          other.isLoadingMore == isLoadingMore &&
152	          other.loadMoreFailed == loadMoreFailed &&
153	          _listEquals(other.entries, entries) &&
154	          _listEquals(other.pendingWrites, pendingWrites));
155	
156	  @override
157	  int get hashCode => Object.hash(
158	    Object.hashAll(entries),
159	    nextCursor,
160	    isLoadingMore,
161	    loadMoreFailed,
162	    Object.hashAll(pendingWrites),
163	  );
164	
165	  @override
166	  String toString() =>
167	      'MeusRegistrosLoaded(entries: ${entries.length}, nextCursor: '
168	      '$nextCursor, isLoadingMore: $isLoadingMore, loadMoreFailed: '
169	      '$loadMoreFailed, pendingWrites: ${pendingWrites.length})';
170	}
171	
172	Entry _placeholderEntryFor(PendingEntryWrite pending) {
173	  final startedAtIso = pending.startedAt.toIso8601String();
174	  return Entry(
175	    id: pending.tempId,
176	    content: pending.content,
177	    source: pending.source,
178	    chatMessageId: null,
179	    occurredAt: startedAtIso,
180	    serverRevision: 0,
181	    createdAt: startedAtIso,
182	    updatedAt: startedAtIso,
183	    mediaDurationSeconds: pending.mediaDurationSeconds,
184	  );
185	}
186	
187	bool _listEquals<T>(List<T> a, List<T> b) {
188	  if (a.length != b.length) {
189	    return false;
190	  }
191	  for (var i = 0; i < a.length; i++) {
192	    if (a[i] != b[i]) {
193	      return false;
194	    }
195	  }
196	  return true;
197	}
