16	/// On success, writes the entry through to the `entries` Hive box (`Box
17	/// <Map>`, keyed by id, raw `EntryDto.toJson()` — Design Notes) *before*
18	/// returning `right(...)`, same "persist then return" ordering
19	/// `AuthRepositoryImpl._authenticate` already uses for its own
20	/// post-success side effect.
21	class EntriesRepositoryImpl implements EntriesRepository {
22	  EntriesRepositoryImpl({
23	    required EntriesRemoteDataSource remoteDataSource,
24	    required Box<Map> entriesBox,
25	  }) : _remoteDataSource = remoteDataSource,
26	       _entriesBox = entriesBox;
27	
28	  final EntriesRemoteDataSource _remoteDataSource;
29	  final Box<Map> _entriesBox;
30	
31	  @override
32	  Future<Either<Failure, Entry>> create({
33	    required String content,
34	    required EntrySource source,
35	    int? mediaDurationSeconds,
36	    String? chatMessageId,
37	  }) async {
38	    final result = await _remoteDataSource.create(
39	      content: content,
40	      source: source,
41	      mediaDurationSeconds: mediaDurationSeconds,
42	      chatMessageId: chatMessageId,
43	    );
44	    return result.match((failure) async => left(failure), (dto) async {
45	      // A thrown Hive/disk exception must never escape unmapped (RNF09) —
46	      // same rationale/fallback `AuthRepositoryImpl` already uses for its
47	      // own local-persistence step.
48	      try {
49	        await _entriesBox.put(dto.id, dto.toJson());
50	      } catch (error) {
51	        return left(Failure.malformedResponse(message: error.toString()));
52	      }
53	      return right(_toEntry(dto));
54	    });
55	  }
56	
57	  @override
58	  Future<Either<Failure, EntriesPage>> list({
59	    String? cursor,
60	    int limit = 20,
61	    EntrySource? source,
62	    DateTime? dateFrom,
63	    DateTime? dateTo,
64	  }) async {
65	    final result = await _remoteDataSource.list(
66	      cursor: cursor,
67	      limit: limit,
68	      source: source,
69	      dateFrom: dateFrom,
70	      dateTo: dateTo,
71	    );
72	    return result.match(
73	      (failure) async {
74	        // Boundaries/Design Notes: the Hive-cache fallback is scoped to
75	        // `cursor == null` (the first/fresh page) only — a paginated
76	        // continuation (`cursor != null`) that fails with
77	        // `networkOffline`/`networkTimeout` propagates as `Left` like any
78	        // other pagination failure instead, so `MeusRegistrosCubit`'s own
79	        // `loadMoreFailed`/retry path handles it uniformly rather than a
80	        // full unrelated cache dump silently replacing the in-progress
81	        // paginated list (and breaking its newest-first ordering).
82	        if (cursor == null &&
83	            (failure is NetworkOffline || failure is NetworkTimeout)) {
84	          return _offlineFallback();
85	        }
86	        return left(failure);
87	      },
88	      (page) async {
89	        try {
90	          await _entriesBox.putAll({
91	            for (final dto in page.items) dto.id: dto.toJson(),
92	          });
93	        } catch (error) {
94	          // Same RNF09 rationale as `create()`'s own Hive-write guard — a
95	          // thrown Hive/disk exception must never escape unmapped.
96	          return left(Failure.malformedResponse(message: error.toString()));
97	        }
98	        return right(
99	          EntriesPage(
100	            items: page.items.map(_toEntry).toList(),
101	            nextCursor: page.nextCursor,
102	          ),
103	        );
104	      },
105	    );
106	  }
107	
108	  @override
109	  Future<Either<Failure, Entry>> getById(String id) async {
110	    final result = await _remoteDataSource.get(id);
111	    return result.match(
112	      (failure) async {
113	        // Boundaries: scoped to networkOffline/networkTimeout specifically
114	        // — every other Failure (notFound included) propagates as Left,
115	        // unmapped, same convention `list()`'s own cursor-scoped fallback
116	        // above uses.
117	        if (failure is NetworkOffline || failure is NetworkTimeout) {
118	          return _cachedEntryOrOriginalFailure(id, failure);
119	        }
120	        return left(failure);
121	      },
122	      (dto) async {
123	        // Same RNF09 rationale as `create()`/`list()`'s own Hive-write
124	        // guards — a thrown Hive/disk exception must never escape
125	        // unmapped.
126	        try {
127	          await _entriesBox.put(dto.id, dto.toJson());
128	        } catch (error) {
129	          return left(Failure.malformedResponse(message: error.toString()));
130	        }
131	        return right(_toEntry(dto));
132	      },
133	    );
134	  }
135	
136	  @override
137	  Future<Either<Failure, List<Entry>>> search(
138	    String query, {
139	    EntrySource? source,
140	    DateTime? dateFrom,
141	    DateTime? dateTo,
142	  }) async {
143	    final result = await _remoteDataSource.search(
144	      query,
145	      source: source,
146	      dateFrom: dateFrom,
147	      dateTo: dateTo,
148	    );
149	    return result.match(
150	      (failure) async {
151	        // Boundaries/AD-9: no cache fallback for search, unlike
152	        // list()/getById() — every Failure (including
153	        // networkOffline/networkTimeout) propagates as Left, unmapped.
154	        return left(failure);
155	      },
156	      (dtos) async {
157	        // Review finding: de-duplicated by id first (first-occurrence-wins,
158	        // same semantics as `MeusRegistrosCubit`'s own trust-but-verify
159	        // convention for server data, shared via `core/utils/
160	        // deduped_by_id.dart`) — so the `putAll` below and the returned
161	        // list stay consistent, and `_SearchResults`' `ListView.builder`
162	        // (keyed by `ValueKey(entry.id)`) never sees a duplicate key even
163	        // if the backend ever violated its own no-duplicate-ids invariant.
164	        final dedupedDtos = dedupedById(dtos, (dto) => dto.id);
165	        // Same RNF09 rationale as create()/list()/getById()'s own
166	        // Hive-write guards — a thrown Hive/disk exception must never
167	        // escape unmapped.
168	        try {
169	          await _entriesBox.putAll({
170	            for (final dto in dedupedDtos) dto.id: dto.toJson(),
171	          });
172	        } catch (error) {
173	          return left(Failure.malformedResponse(message: error.toString()));
174	        }
175	        return right(dedupedDtos.map(_toEntry).toList());
176	      },
177	    );
178	  }
179	
180	  /// [getById]'s own offline/timeout fallback (Boundaries): a cache hit
181	  /// returns `Right` from the cached `EntryDto`; a cache miss propagates
182	  /// [originalFailure] unchanged — "no synthesized not-found" — rather than
183	  /// inventing a [Failure.notFound] this repository never actually
184	  /// received from the backend. A corrupt cached entry (should never
185	  /// happen — every entry here was written by [create]/[list]/[getById]
186	  /// themselves) maps to `Left(malformedResponse)` rather than throwing
187	  /// (RNF09), same guard `_offlineFallback()`'s own malformed-cache check
188	  /// uses.
189	  Either<Failure, Entry> _cachedEntryOrOriginalFailure(
190	    String id,
191	    Failure originalFailure,
192	  ) {
193	    try {
194	      final cached = _entriesBox.get(id);
195	      if (cached == null) {
196	        return left(originalFailure);
197	      }
198	      return right(
199	        _toEntry(EntryDto.fromJson(Map<String, dynamic>.from(cached))),
200	      );
201	    } catch (error) {
202	      return left(Failure.malformedResponse(message: error.toString()));
203	    }
204	  }
205	
206	  /// The offline/timeout fallback (Boundaries): a full `entries` Hive box
207	  /// dump, sorted `occurredAt` desc, always `nextCursor: null` — a cached
208	  /// dump has no further page to request. A corrupt cached entry (should
209	  /// never happen — every entry here was written by [create]/[list]
210	  /// themselves) maps to `Left(malformedResponse)` rather than throwing
211	  /// (RNF09), same guard `create()`'s own Hive write already has.
212	  Either<Failure, EntriesPage> _offlineFallback() {
213	    try {
214	      final entries =
215	          _entriesBox.values
216	              .map(
217	                (json) => _toEntry(
218	                  EntryDto.fromJson(Map<String, dynamic>.from(json)),
219	                ),
220	              )
221	              .toList()
222	            ..sort(
223	              (a, b) =>
224	                  DateTime.parse(b.occurredAt)
225	                      .compareTo(DateTime.parse(a.occurredAt)),
226	            );
227	      return right(EntriesPage(items: entries, nextCursor: null));
228	    } catch (error) {
229	      return left(Failure.malformedResponse(message: error.toString()));
230	    }
231	  }
232	
233	  @override
234	  Future<Either<Failure, Unit>> clearLocalCache() async {
235	    try {
236	      await _entriesBox.clear();
237	      return right(unit);
238	    } catch (error) {
239	      // Same RNF09 rationale as every other Hive-write guard in this file.
240	      return left(Failure.malformedResponse(message: error.toString()));
241	    }
242	  }
243	
244	  Entry _toEntry(EntryDto dto) => Entry(
245	    id: dto.id,
246	    content: dto.content,
247	    source: dto.source,
248	    chatMessageId: dto.chatMessageId,
249	    occurredAt: dto.occurredAt,
250	    serverRevision: dto.serverRevision,
251	    createdAt: dto.createdAt,
252	    updatedAt: dto.updatedAt,
253	    mediaDurationSeconds: dto.mediaDurationSeconds,
254	  );
255	}
