924	/// "Hoje"/"Ontem"/`dd/mm/yyyy` — presentation's own job (Code Map: day
925	/// labels aren't the pure `groupEntriesByDate()`'s concern). [date] is
926	/// always already truncated to local midnight (`EntryDateGroup`'s own
927	/// contract).
928	String _dayLabel(DateTime date) {
929	  final now = DateTime.now();
930	  final today = DateTime(now.year, now.month, now.day);
931	  final yesterday = today.subtract(const Duration(days: 1));
932	  if (date == today) {
933	    return 'Hoje';
934	  }
935	  if (date == yesterday) {
936	    return 'Ontem';
937	  }
938	  final day = date.day.toString().padLeft(2, '0');
939	  final month = date.month.toString().padLeft(2, '0');
940	  return '$day/$month/${date.year}';
941	}
