8	/// The entries feature's one write call so far (`entries-create`) — posts
9	/// via the shared `ApiClient`, mirroring `account_remote_data_source.dart`'s
10	/// pattern.
11	class EntriesRemoteDataSource {
12	  EntriesRemoteDataSource(this._apiClient);
13	
14	  final ApiClient _apiClient;
15	
16	  /// Sends `{content, source}` plus `mediaDurationSeconds`/`chatMessageId`
17	  /// only when non-null (spec-3-2's `source: audio` entries;
18	  /// spec-6-4/RF10's `source: chat` entries, mirroring the exact same
19	  /// optional-field convention) — `occurredAt` still never sent (Boundaries:
20	  /// no `Entry` field beyond the modeled 9; that one belongs to a later
21	  /// epic).
22	  Future<Either<Failure, EntryDto>> create({
23	    required String content,
24	    required EntrySource source,
25	    int? mediaDurationSeconds,
26	    String? chatMessageId,
27	  }) async {
28	    final result = await _apiClient.post(
29	      'entries-create',
30	      data: {
31	        'content': content,
32	        'source': source.name,
33	        'mediaDurationSeconds': ?mediaDurationSeconds,
34	        'chatMessageId': ?chatMessageId,
35	      },
36	    );
37	    return result.flatMap((json) {
38	      try {
39	        final data = json['data'] as Map<String, dynamic>;
40	        return right(EntryDto.fromJson(data));
41	      } catch (error) {
42	        // A 200 response that doesn't match the expected shape is a
43	        // client-side parse failure, never a backend-sent code — maps to
44	        // the local-only `malformedResponse` (RNF09: no exception escapes
45	        // unmapped).
46	        return left(Failure.malformedResponse(message: error.toString()));
47	      }
48	    });
49	  }
50	
51	  /// Calls `entries-list` (`ApiClient.get`) with `limit` always sent, and
52	  /// `cursor`/`source`/`dateFrom`/`dateTo` only when non-null (spec-4-1's
53	  /// own convention for an optional-in-the-contract query parameter,
54	  /// mirroring [create]'s own `mediaDurationSeconds` handling — spec-5-2
55	  /// extends it to these three new filter params). [source] is sent as
56	  /// its own `.name` (the contract's own enum string); [dateFrom]/
57	  /// [dateTo] as `.toUtc().toIso8601String()` — Review finding: a local
58	  /// (non-UTC) `DateTime.toIso8601String()` has no `Z`/offset suffix,
59	  /// which isn't valid RFC3339 and so doesn't satisfy the contract's own
60	  /// `format: date-time` (`openapi.yaml`). Converting to UTC only here,
61	  /// at the serialization boundary, keeps every caller's own local-
62	  /// calendar computation (`EntriesFilterSheet`'s "local midnight this
63	  /// Monday"/"the 1st of this month") correct — this data source never
64	  /// computes the range itself, only forwards whatever
65	  /// [EntriesRepository.list]'s own caller already resolved. Returns the
66	  /// raw page as a record — no dedicated DTO wrapper type, since
67	  /// `EntriesRepositoryImpl.list()` is this record's only reader.
68	  Future<Either<Failure, ({List<EntryDto> items, String? nextCursor})>> list({
69	    String? cursor,
70	    int limit = 20,
71	    EntrySource? source,
72	    DateTime? dateFrom,
73	    DateTime? dateTo,
74	  }) async {
75	    final result = await _apiClient.get(
76	      'entries-list',
77	      queryParameters: {
78	        'limit': limit,
79	        'cursor': ?cursor,
80	        'source': ?source?.name,
81	        'dateFrom': ?dateFrom?.toUtc().toIso8601String(),
82	        'dateTo': ?dateTo?.toUtc().toIso8601String(),
83	      },
84	    );
85	    return result.flatMap((json) {
86	      try {
87	        final data = json['data'] as List<dynamic>;
88	        final items = data
89	            .map((item) => EntryDto.fromJson(item as Map<String, dynamic>))
